Below is a step-by-step introduction to building a toy “query parser” that takes a pre-parsed SQL AST (Abstract Syntax Tree) and converts it into a relational algebra (RA) expression tree. We start with minimal building blocks and simple SELECT statements, then expand while preserving basic error handling and highlighting common pitfalls.

What we will cover:
- Step 0: Define minimal SQL and RA ASTs plus a pretty-printer to visualize results.
- Step 1: Translator for simple SELECT ... FROM single_table [WHERE ...], with basic validation.
- Step 2: Expand to multiple tables (implicit cross-product) in FROM, with examples.
- Pitfalls and examples: Show typical issues and the resulting RA trees or errors.

Step 0 — Foundations: AST definitions and pretty-printing
The SQL AST captures the structure of a query (columns, literals, predicates, tables, etc.). The RA AST represents logical operators like Table (base relation), Selection (σ), Projection (π), and Product (×).

python
from __future__ import annotations
from dataclasses import dataclass
from typing import List, Optional

# ---------- Exceptions: focused, useful messages ----------

class TranslationError(Exception):
    pass

class EmptyFromError(TranslationError):
    pass

class EmptySelectListError(TranslationError):
    pass


# ---------- SQL AST (minimal) ----------

class SQLExpr:
    pass

@dataclass
class Column(SQLExpr):
    name: str
    table: Optional[str] = None  # qualified as table.column if given

@dataclass
class Literal(SQLExpr):
    value: object

@dataclass
class Comparison(SQLExpr):
    op: str  # e.g., '=', '<', '>'
    left: SQLExpr
    right: SQLExpr

@dataclass
class BooleanOp(SQLExpr):
    op: str  # 'AND' or 'OR'
    left: SQLExpr
    right: SQLExpr

@dataclass
class Not(SQLExpr):
    expr: SQLExpr

@dataclass
class SelectItem:
    expr: SQLExpr
    alias: Optional[str] = None

@dataclass
class AllColumns(SQLExpr):
    # Represents SELECT *
    pass

@dataclass
class TableRef:
    name: str
    alias: Optional[str] = None

@dataclass
class SelectStmt:
    select_list: List[SelectItem]         # items in SELECT clause
    from_tables: List[TableRef]           # tables in FROM clause
    where: Optional[SQLExpr] = None       # optional WHERE predicate


# ---------- Relational Algebra AST (minimal) ----------

class RAExpr:
    pass

@dataclass
class RATable(RAExpr):
    name: str
    alias: Optional[str] = None

@dataclass
class RAProduct(RAExpr):
    left: RAExpr
    right: RAExpr

@dataclass
class RASelection(RAExpr):
    predicate: SQLExpr
    child: RAExpr

@dataclass
class RAProjection(RAExpr):
    items: List[SelectItem]  # project expressions (and aliases)
    child: RAExpr


# ---------- Pretty printing helpers ----------

def expr_to_str(e: SQLExpr) -> str:
    if isinstance(e, Column):
        return f"{e.table}.{e.name}" if e.table else e.name
    if isinstance(e, Literal):
        return repr(e.value)
    if isinstance(e, Comparison):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, BooleanOp):
        return f"({expr_to_str(e.left)} {e.op} {expr_to_str(e.right)})"
    if isinstance(e, Not):
        return f"(NOT {expr_to_str(e.expr)})"
    if isinstance(e, AllColumns):
        return "*"
    return f"<expr:{e.__class__.__name__}>"

def ra_to_str(ra: RAExpr, indent: int = 0) -> str:
    pad = "  " * indent
    if isinstance(ra, RATable):
        alias = f" AS {ra.alias}" if ra.alias else ""
        return f"{pad}Table({ra.name}{alias})"
    if isinstance(ra, RAProduct):
        return f"{pad}Product\n{ra_to_str(ra.left, indent+1)}\n{ra_to_str(ra.right, indent+1)}"
    if isinstance(ra, RASelection):
        return f"{pad}Select[{expr_to_str(ra.predicate)}]\n{ra_to_str(ra.child, indent+1)}"
    if isinstance(ra, RAProjection):
        items = ", ".join(
            f"{expr_to_str(i.expr)}" + (f" AS {i.alias}" if i.alias else "")
            for i in ra.items
        )
        return f"{pad}Project[{items}]\n{ra_to_str(ra.child, indent+1)}"
    return f"{pad}<RA:{ra.__class__.__name__}>"


Step 1 — Single-table SELECT-FROM-[WHERE]
For a single table, the relational algebra plan is:
- RATable as the base
- Optionally RASelection for WHERE
- RAProjection for the SELECT list (except for SELECT * where you can omit the projection)

We include basic validation to catch missing FROM or empty SELECT lists early.

python
def translate_select_single_table(stmt: SelectStmt) -> RAExpr:
    # Basic validation
    if not stmt.from_tables:
        raise EmptyFromError("Missing FROM clause.")
    if len(stmt.from_tables) != 1:
        raise TranslationError("This step supports exactly one table in FROM.")
    if not stmt.select_list:
        raise EmptySelectListError("Empty SELECT list is not allowed.")

    # Base relation
    base = stmt.from_tables[0]
    ra: RAExpr = RATable(name=base.name, alias=base.alias)

    # WHERE -> selection
    if stmt.where is not None:
        ra = RASelection(predicate=stmt.where, child=ra)

    # SELECT list -> projection (omit if SELECT *)
    only_star = (
        len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
    )
    if only_star:
        return ra
    else:
        return RAProjection(items=stmt.select_list, child=ra)


# ---------- Examples (Step 1) ----------

# SELECT id, name FROM users WHERE age > 18;
stmt1 = SelectStmt(
    select_list=[SelectItem(Column("id")), SelectItem(Column("name"))],
    from_tables=[TableRef("users")],
    where=Comparison(">", Column("age"), Literal(18)),
)
ra1 = translate_select_single_table(stmt1)
print("Step 1 plan:\n" + ra_to_str(ra1))

# SELECT * FROM users;
stmt2 = SelectStmt(
    select_list=[SelectItem(AllColumns())],
    from_tables=[TableRef("users")],
    where=None,
)
ra2 = translate_select_single_table(stmt2)
print("\nStep 1 plan (SELECT *):\n" + ra_to_str(ra2))

# Example: error when FROM is missing
try:
    bad = SelectStmt(select_list=[SelectItem(Column("id"))], from_tables=[], where=None)
    translate_select_single_table(bad)
except TranslationError as e:
    print("\nStep 1 error (no FROM):", e)


Step 2 — Multiple tables in FROM (implicit cross-product)
Now we allow multiple tables in the FROM clause. The classic semantics for comma-separated tables is a cross-product of all tables, then the WHERE predicate (which can express join conditions), then the projection.

Algorithm:
- Fold the list of tables into a left-deep RAProduct chain: (((T1 × T2) × T3) × ...).
- Apply WHERE as RASelection above that product.
- Apply RAProjection (unless SELECT *).

python
def fold_product(tables: List[TableRef]) -> RAExpr:
    assert len(tables) >= 1
    ra: RAExpr = RATable(tables[0].name, alias=tables[0].alias)
    for tr in tables[1:]:
        ra = RAProduct(left=ra, right=RATable(tr.name, alias=tr.alias))
    return ra

def translate_select_multi_table(stmt: SelectStmt) -> RAExpr:
    # Validation
    if not stmt.from_tables:
        raise EmptyFromError("Missing FROM clause.")
    if not stmt.select_list:
        raise EmptySelectListError("Empty SELECT list is not allowed.")

    # Build product of all tables (or a single table if len == 1)
    ra: RAExpr = fold_product(stmt.from_tables)

    # WHERE -> selection
    if stmt.where is not None:
        ra = RASelection(predicate=stmt.where, child=ra)

    # SELECT list -> projection (omit if SELECT *)
    only_star = (
        len(stmt.select_list) == 1 and isinstance(stmt.select_list[0].expr, AllColumns)
    )
    if only_star:
        return ra
    else:
        return RAProjection(items=stmt.select_list, child=ra)


# ---------- Example (Step 2) ----------
# SELECT u.id, o.total
# FROM users AS u, orders AS o
# WHERE u.id = o.user_id AND o.total > 100;
stmt3 = SelectStmt(
    select_list=[SelectItem(Column("id", table="u")),
                 SelectItem(Column("total", table="o"))],
    from_tables=[TableRef("users", alias="u"), TableRef("orders", alias="o")],
    where=BooleanOp(
        "AND",
        left=Comparison("=", Column("id", "u"), Column("user_id", "o")),
        right=Comparison(">", Column("total", "o"), Literal(100)),
    ),
)
ra3 = translate_select_multi_table(stmt3)
print("\nStep 2 plan (multi-table):\n" + ra_to_str(ra3))


Common pitfalls and how this setup helps
- Missing FROM clause: Caught by EmptyFromError.
- Empty SELECT list: Caught by EmptySelectListError.
- Ambiguous or unknown column names: This minimal translator does not resolve names; in the next iteration you would add a name resolution pass that qualifies unqualified columns and raises clear UnknownColumn or AmbiguousColumn errors.
- SELECT * handling: We omit the projection node when only SELECT * is present, which keeps plans concise and mirrors RA semantics.

Next steps you can take
- Add explicit JOIN ... ON ... syntax: introduce a JoinRef in the SQL AST and translate to RAProduct + RASelection or a dedicated RAJoin node.
- Add name resolution and a simple catalog to validate table/column existence and catch ambiguity early.
- Extend expressions: arithmetic, functions, and support for GROUP BY/aggregates (e.g., RAGroupBy).
